using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class CorruptionStats : MonoBehaviour
{
	[Header("Effects")]
	[SerializeField]
	protected EffectsList effectsList;

	[Header("Components")]
	[SerializeField]
	protected SpriteControl spriteControl;

	[SerializeField]
	protected UnitEffects unitEffects;

	[Header("VFX")]
	[SerializeField]
	private GameObject purifyCorruptFeedbackPrefab;

	[SerializeField]
	private GameObject blockedFeedbackPrefab;

	[Header("SFX")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private CorruptAction corruptAction;

	[Header("Achievement")]
	[SerializeField]
	[HideIf("companionReward")]
	private AchievementData heavyPurgerAchievementData;

	[Header("Hypersensitive Aura")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[Header("Debug")]
	[SerializeField]
	protected bool verbose;

	[Header("Companion Reward")]
	[SerializeField]
	private bool companionReward;

	[ShowNonSerializedField]
	protected float currentCorruption;

	protected float maxCorruption;

	private bool oldCorruptionRegistered;

	protected float oldCorruption;

	protected Coroutine spawnFeedbackCoroutine;

	private List<Action<FeedbackDirectionEnum>> feedbacksActionList = new List<Action<FeedbackDirectionEnum>>();

	private Coroutine updateCorruptionDelayCoroutine;

	private bool corrupted;

	private bool purified;

	public float CurrentCorruption => currentCorruption;

	public float MaxCorruption => maxCorruption;

	public virtual int Purify(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		if (amount != -1)
		{
			amount = CheckMinimize(amount, source);
			if (amount > -1 || corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.ELDRITCHCONNECTIONINFINITY)
			{
				if (corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.ELDRITCHCONNECTIONINFINITY)
				{
					amount = 9999;
				}
				amount = ReferenceSingleton<PurifyOmensHandler>.Instance.OnAnyTargetReceivePurifyModifiers(amount);
				amount = GetAfterMinimizePurifyModifier(amount, source);
				if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
				{
					if (!unitEffects.IsHornetDust())
					{
						effectsList.HornetDustEffect.CheckIfAnotherEnemyIsHornetDustAndRemoveIt(base.gameObject);
					}
					int num = unitEffects.IsHornetDustGetAmount();
					amount += num;
				}
				if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
				{
					amount = ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnTargetModifier(amount, base.gameObject);
				}
				int num2 = unitEffects.IsEffectActiveGetAmount(effectsList.SerenityEffect, activateFeedback: false);
				amount += num2;
				amount = CheckHypersensitiveAuraEffect(amount);
				if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
				{
					amount = ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyFinalModifier(amount);
				}
				if (corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.PIERCE)
				{
					int startingAmount = amount;
					amount = GetPurifyAmountWithDefensiveModifiers(amount);
					CheckPurifyBlockFeedback(amount, startingAmount);
				}
				RegisterOldCorruption();
				ChangeCurrentCorruption(-amount, corruptionPurifyModifierEnum);
			}
			if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
			{
				ReferenceSingleton<CellariusOmensHandler>.Instance.ActivateAncientHelmOmen((amount == EffectsValues.INFINITY_PURIFY) ? 999 : amount);
			}
		}
		unitEffects.OnPurifyEffects(currentCorruption, source, amount);
		if (corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.ELDRITCHCONNECTIONINFINITY)
		{
			amount = EffectsValues.INFINITY_PURIFY;
		}
		if (amount > 0 || amount == EffectsValues.INFINITY_PURIFY)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.OnUnitPurified(amount, source);
			if (amount >= heavyPurgerAchievementData.AchievementVariableAmount || amount == EffectsValues.INFINITY_PURIFY)
			{
				heavyPurgerAchievementData.Unlock();
			}
			if (amount > 0)
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.SetHighestPurification(amount);
			}
			if (playSFX)
			{
				purifyAction.PlaySFX();
			}
			purified = true;
			int feedbackAmount = amount;
			feedbacksActionList.Add(delegate(FeedbackDirectionEnum feedbackDirectionEnum)
			{
				SpawnPurifyCorruptFeedback(purify: true, feedbackAmount, feedbackDirectionEnum);
			});
			if (spawnFeedbackCoroutine == null)
			{
				spawnFeedbackCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(SpawnPurifyCorruptFeedbacks());
			}
			if (updateCorruptionDelayCoroutine == null)
			{
				updateCorruptionDelayCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(UpdateCorruptionDelay(corruptionPurifyModifierEnum));
			}
		}
		$"{base.name}: purified by {amount}".DebugLogIfVerbose(verbose);
		return amount;
	}

	private int CheckMinimize(int amount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && source.GetComponent<UnitEffects>().IsMinimizeActive())
		{
			return 1;
		}
		return amount;
	}

	public int CheckHypersensitiveAuraEffect(int amount)
	{
		int num = currentActiveUnits.IsHypersensitiveAuraEffectActiveGetAmount();
		if (num <= 0)
		{
			return amount;
		}
		return amount * (int)Mathf.Pow(2f, num);
	}

	protected virtual int GetPurifyAmountWithDefensiveModifiers(int amount)
	{
		int num = unitEffects.IsEffectActiveGetAmount(effectsList.ThickSkinEffect);
		amount = Mathf.Max(amount - num, 0);
		if (amount > 0)
		{
			int num2 = unitEffects.IsEffectActiveGetAmount(effectsList.ReinforcedEffect, activateFeedback: false);
			if (num2 > 0)
			{
				if (num2 - amount <= 0)
				{
					unitEffects.IsEffectActiveWithActivation(effectsList.ReinforcedEffect, activateFeedback: false);
				}
				else
				{
					unitEffects.DecreaseEffect(effectsList.ReinforcedEffect, 1);
				}
				amount = 0;
			}
			else
			{
				int num3 = unitEffects.IsEffectActiveGetAmountAndDecreaseEffect(effectsList.ShadowMantleEffect, amount, activateFeedback: false);
				if (num3 > 0)
				{
					amount = Mathf.Max(amount - num3, 0);
				}
			}
		}
		return amount;
	}

	private void CheckPurifyBlockFeedback(int amount, int startingAmount)
	{
		if (amount != startingAmount)
		{
			int purifyBlockedAmount = startingAmount - amount;
			feedbacksActionList.Add(delegate(FeedbackDirectionEnum feedbackDirectionEnum)
			{
				SpawnBlockFeedback(purifyBlocked: true, purifyBlockedAmount, feedbackDirectionEnum);
			});
			if (spawnFeedbackCoroutine == null)
			{
				spawnFeedbackCoroutine = StartCoroutine(SpawnPurifyCorruptFeedbacks());
			}
		}
	}

	protected virtual int GetAfterMinimizePurifyModifier(int amount, GameObject source)
	{
		return amount;
	}

	private void RegisterOldCorruption()
	{
		if (!oldCorruptionRegistered)
		{
			oldCorruptionRegistered = true;
			oldCorruption = currentCorruption;
		}
	}

	public virtual int Corrupt(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		if (!(this is PlayerCorruptionStats))
		{
			DodgeEffect dodgeEffect = effectsList.DodgeEffect;
			if (unitEffects.IsEffectActive(effectsList.SmokeBombEffect, activateFeedback: false))
			{
				if (dodgeEffect.CheckDodge(effectsList.SmokeBombEffect.DodgePercentage, unitEffects, normalDodge: false, GetCorruptionWithOffensiveModifiers(amount, corruptionPurifyModifierEnum), source))
				{
					unitEffects.IsEffectActive(effectsList.SmokeBombEffect);
					amount = -1;
				}
				else
				{
					amount = CheckDodge(amount, corruptionPurifyModifierEnum, source);
				}
			}
			else
			{
				amount = CheckDodge(amount, corruptionPurifyModifierEnum, source);
			}
		}
		if (amount != -1)
		{
			amount = GetCorruptionWithOffensiveModifiers(amount, corruptionPurifyModifierEnum);
			if (corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.PIERCE)
			{
				int num = amount;
				amount = GetCorruptionAmountWithDefensiveModifiers(amount, corruptionPurifyModifierEnum, source);
				int num2 = num - amount;
				if (num2 > 0)
				{
					CheckCorruptionBlockFeedback(num2);
					OnCorruptionBlocked(num2, source);
				}
			}
			if (this is PlayerCorruptionStats)
			{
				amount = ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptedFinalModifier(amount);
			}
			RegisterOldCorruption();
			ChangeCurrentCorruption(amount, corruptionPurifyModifierEnum);
		}
		unitEffects.OnCorruptEffects(source, amount);
		if (amount > 0)
		{
			if (playSFX)
			{
				corruptAction.PlaySFX();
			}
			corrupted = true;
			int feedbackAmount = amount;
			feedbacksActionList.Add(delegate(FeedbackDirectionEnum feedbackDirectionEnum)
			{
				SpawnPurifyCorruptFeedback(purify: false, feedbackAmount, feedbackDirectionEnum);
			});
			Debug.Log("spawnFeedbackCoroutine: " + spawnFeedbackCoroutine);
			if (spawnFeedbackCoroutine == null)
			{
				spawnFeedbackCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(SpawnPurifyCorruptFeedbacks());
			}
			if (updateCorruptionDelayCoroutine == null)
			{
				updateCorruptionDelayCoroutine = ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(UpdateCorruptionDelay(corruptionPurifyModifierEnum));
			}
		}
		$"{base.name}: corrupted by {amount}".DebugLogIfVerbose(verbose);
		return amount;
	}

	protected int GetCorruptionWithOffensiveModifiers(int amount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.ANOMALY || corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION || corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.FORCEFULSTREAM)
		{
			return amount;
		}
		int num = unitEffects.IsEffectActiveGetAmount(effectsList.TormentEffect, activateFeedback: false);
		amount += num;
		int num2 = unitEffects.IsEffectActiveGetAmount(effectsList.VendettaEffect, activateFeedback: false);
		amount += num2;
		amount = CheckHypersensitiveAuraEffect(amount);
		amount = GetCorruptionAmountWithCorruptionIncreaseModifiers(amount);
		if (unitEffects.IsEffectActive(effectsList.SmokeBombEffect, activateFeedback: false))
		{
			amount *= 2;
		}
		return amount;
	}

	protected int CheckDodge(int amount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum, GameObject source)
	{
		int num = unitEffects.IsEffectActiveGetAmount(effectsList.DodgeEffect, activateFeedback: false);
		if (num > 0 && effectsList.DodgeEffect.CheckDodge(num, unitEffects, normalDodge: true, GetCorruptionWithOffensiveModifiers(amount, corruptionPurifyModifierEnum), source))
		{
			return -1;
		}
		return amount;
	}

	protected virtual int GetCorruptionAmountWithDefensiveModifiers(int amount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum, GameObject source)
	{
		if (corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.ANOMALY)
		{
			int num = unitEffects.IsEffectActiveGetAmount(effectsList.RockPlateEffect);
			amount = Mathf.Max(amount - num, 0);
		}
		if (unitEffects.IsEffectActiveWithActivation(effectsList.IncorruptibleEffect))
		{
			amount = 0;
		}
		else
		{
			bool flag = false;
			if (this is PlayerCorruptionStats)
			{
				if ((ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) || ReferenceSingleton<BattleHandler>.Instance.IsSourceCompanions(source)) && ReferenceSingleton<HeveliusOmensHandler>.Instance.IsGlowingReactorOmenActive())
				{
					flag = true;
				}
				if (ReferenceSingleton<SothisOmensHandler>.Instance.BehenianHourglassActive && corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.AFFLICTIONRELIEF)
				{
					flag = true;
				}
			}
			if (!flag)
			{
				int num2 = unitEffects.IsEffectActiveGetAmountAndDecreaseEffect(effectsList.LightShieldEffect, amount, activateFeedback: false);
				if (num2 > 0)
				{
					amount = Mathf.Max(amount - num2, 0);
				}
			}
			if (amount > 0 && unitEffects.IsEffectActiveAndDecreaseEffect(effectsList.BarrierEffect, 1))
			{
				amount = 0;
			}
		}
		return amount;
	}

	private void CheckCorruptionBlockFeedback(int corruptionBlockedAmount)
	{
		feedbacksActionList.Add(delegate(FeedbackDirectionEnum feedbackDirectionEnum)
		{
			SpawnBlockFeedback(purifyBlocked: false, corruptionBlockedAmount, feedbackDirectionEnum);
		});
		if (spawnFeedbackCoroutine == null)
		{
			spawnFeedbackCoroutine = StartCoroutine(SpawnPurifyCorruptFeedbacks());
		}
	}

	protected virtual void OnCorruptionBlocked(int corruptionBlockedAmount, GameObject source)
	{
	}

	protected virtual int GetCorruptionAmountWithCorruptionIncreaseModifiers(int amount)
	{
		return amount;
	}

	protected virtual void ChangeCurrentCorruption(int amount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		currentCorruption += amount;
	}

	private IEnumerator UpdateCorruptionDelay(CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		yield return InvokeAlternatives.WaitForFrames(ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption);
		UpdateCorruption(corruptionPurifyModifierEnum);
		if (currentCorruption < oldCorruption)
		{
			PurifiedMoreThanCorrupted();
		}
		else if (currentCorruption > oldCorruption)
		{
			CorruptedMoreThanPurified();
		}
		else if (corrupted)
		{
			CorruptedMoreThanPurified();
		}
		else if (purified)
		{
			PurifiedMoreThanCorrupted();
		}
		oldCorruptionRegistered = false;
		updateCorruptionDelayCoroutine = null;
		corrupted = false;
		purified = false;
	}

	protected virtual void UpdateCorruption(CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		currentCorruption = Mathf.Clamp(currentCorruption, 0f, maxCorruption);
		if (this is PlayerCorruptionStats)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerPurifiedCorruptedCheckZenithRingOmenFeedback(currentCorruption);
		}
	}

	protected virtual void CorruptedMoreThanPurified()
	{
	}

	protected virtual void PurifiedMoreThanCorrupted()
	{
	}

	private IEnumerator SpawnPurifyCorruptFeedbacks()
	{
		yield return InvokeAlternatives.WaitForFrames(ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption);
		int feedbackAmount = feedbacksActionList.Count;
		bool right = UnityEngine.Random.Range(0, 2) == 0;
		for (int i = 0; i < feedbacksActionList.Count; i++)
		{
			if (right)
			{
				feedbacksActionList[i](FeedbackDirectionEnum.RIGHT);
			}
			else
			{
				feedbacksActionList[i](FeedbackDirectionEnum.LEFT);
			}
			right = !right;
			yield return new WaitForSeconds((feedbackAmount >= 3) ? 0.1f : 0.2f);
		}
		feedbacksActionList.Clear();
		spawnFeedbackCoroutine = null;
	}

	private void SpawnPurifyCorruptFeedback(bool purify, int amount, FeedbackDirectionEnum feedbackDirectionEnum)
	{
		ReferenceSingleton<PoolHandler>.Instance.GetObject(purifyCorruptFeedbackPrefab.name).GetComponent<PurifyCorruptTextFeedback>().PlayPurifyCorruptFeedback(amount, purify, base.transform.position, feedbackDirectionEnum);
	}

	private void SpawnBlockFeedback(bool purifyBlocked, int amountBlocked, FeedbackDirectionEnum feedbackDirectionEnum)
	{
		ReferenceSingleton<PoolHandler>.Instance.GetObject(blockedFeedbackPrefab.name).GetComponent<PurifyCorruptTextFeedback>().PlayBlockFeedback(purifyBlocked, amountBlocked, base.transform.position, feedbackDirectionEnum);
	}

	public float GetCorruptionPercentage()
	{
		return currentCorruption / maxCorruption;
	}

	public virtual bool IsDefeated()
	{
		return false;
	}
}
